static void one(unsigned phase,unsigned path,ULONG access){static const wchar_t* names[]={L"\\",L"\\KnownDlls",L"\\KnownDlls32"};DWORD hb=0,ha=0;GetProcessHandleCount(GetCurrentProcess(),&hb);UNICODE_STRING n{};n.Length=USHORT(wcslen(names[path])*2);n.MaximumLength=n.Length+2;n.Buffer=const_cast<PWSTR>(names[path]);OBJECT_ATTRIBUTES a{};a.Length=sizeof(a);a.ObjectName=&n;a.Attributes=0x40;HANDLE h=nullptr;LONG status=op(&h,access,&a);ULONG grant=0;LONG closed=LONG(0xDEADBEEF);if(status>=0){ULONG data[14]{},length=0;if(!h||query(h,0,data,sizeof(data),&length)<0||length!=sizeof(data))fail("basic");grant=data[1];closed=close_nt(h);if(closed<0)fail("close");}GetProcessHandleCount(GetCurrentProcess(),&ha);printf("case=%u width=%zu phase=%u path=%u access=%08lX status=%08lX dos=%lu grant=%08lX close=%08lX handles-before=%lu handles-after=%lu\n",cases++,sizeof(void*),phase,path,access,ULONG(status),dos(status),grant,ULONG(closed),hb,ha);if(hb!=ha)fail("lifetime");}
int main(){setvbuf(stdout,nullptr,_IONBF,0);auto n=GetModuleHandleW(L"ntdll.dll");op=reinterpret_cast<Open>(GetProcAddress(n,"NtOpenDirectoryObject"));query=reinterpret_cast<Query>(GetProcAddress(n,"NtQueryObject"));close_nt=reinterpret_cast<Close>(GetProcAddress(n,"NtClose"));dos=reinterpret_cast<Dos>(GetProcAddress(n,"RtlNtStatusToDosError"));if(!op||!query||!close_nt||!dos)return 22;LUID luid{};if(!LookupPrivilegeValueW(nullptr,L"SeSecurityPrivilege",&luid))fail("luid-warmup");DWORD before=0,after=0;GetProcessHandleCount(GetCurrentProcess(),&before);HANDLE primary=nullptr,token=nullptr,saved_thread=nullptr;if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY|TOKEN_DUPLICATE,&primary))fail("open-primary");auto primary_original=privileges(primary);if(!OpenThreadToken(GetCurrentThread(),TOKEN_QUERY|TOKEN_IMPERSONATE,TRUE,&saved_thread)&&GetLastError()!=ERROR_NO_TOKEN)fail("save-thread-token");if(!DuplicateTokenEx(primary,TOKEN_QUERY|TOKEN_ADJUST_PRIVILEGES|TOKEN_IMPERSONATE,nullptr,SecurityImpersonation,TokenImpersonation,&token))fail("duplicate-own-token");if(!SetThreadToken(nullptr,token))fail("impersonate-own-token");auto original=privileges(token);DWORD attributes=selected(original,luid);if(attributes==0xFFFFFFFF)fail("privilege-absent");for(unsigned phase=0;phase<3;phase++){BOOL changed=TRUE;DWORD error=0;if(phase!=0){TOKEN_PRIVILEGES p{};p.PrivilegeCount=1;p.Privileges[0].Luid=luid;p.Privileges[0].Attributes=phase==1?SE_PRIVILEGE_ENABLED:attributes;SetLastError(0);changed=AdjustTokenPrivileges(token,FALSE,&p,0,nullptr,nullptr);error=GetLastError();}auto current=privileges(token);printf("phase=%u adjust-ok=%u adjust-error=%lu attributes=%08lX token-bytes=%zu\n",phase,changed,error,selected(current,luid),current.size());if(!changed||error!=0)fail("adjust-own-token");for(unsigned path=0;path<3;path++)for(ULONG access:{0x01000000u,0x01000001u,0x01000004u,0x03000000u,0x03000003u,0x010F000Fu,0x02000000u,0xFFFFFFFFu})one(phase,path,access);}if(privileges(token)!=original)fail("restore-own-token");if(!SetThreadToken(nullptr,saved_thread))fail("restore-thread-token");if(privileges(primary)!=primary_original)fail("primary-token-changed");if(saved_thread&&!CloseHandle(saved_thread))fail("close-saved-thread");if(!CloseHandle(primary))fail("close-primary");if(!CloseHandle(token))fail("close-token");GetProcessHandleCount(GetCurrentProcess(),&after);printf("complete cases=%u token-restored=1 primary-unchanged=1 thread-restored=1 handles-before=%lu handles-after=%lu\n",cases,before,after);return before==after?0:23;}
